import express from 'express';
import itemsRoutes from './invoice-items/invoice.routes.js';
import invoiceTotalRoutes from './total-invoices/invoice-total.routes.js';
import { authGuard } from '../../shared/middleware/authGuard.middleware.js';
import { tenantContext } from '../../shared/middleware/tenantContext.middleware.js';
const invoiceRoot = express.Router();
invoiceRoot.use(authGuard, tenantContext);
invoiceRoot.use("/:invoiceId/items", itemsRoutes);
invoiceRoot.use("/main", invoiceTotalRoutes);
export default invoiceRoot;
